#!/usr/bin/env bash
# Run from a workspace containing zenmath; records are generated by the MPFR tools.
set -euo pipefail
records=${1:?usage: check-core-math.sh RECORD_DIRECTORY}
cargo test -p zenmath
cargo clippy -p zenmath --all-targets --all-features -- -D warnings
cargo build -p zenmath --examples --release
for f in exp2f expf log2f logf log10f cbrtf powf sinf cosf tanf atanf atan2f tanhf log1pf expm1f; do
    "${CARGO_TARGET_DIR:-target}/release/examples/core_math_check" "$f" "$records/$f.bin"
done
for f in cbrt exp2 exp log2 log log10 atan log1p; do
    "${CARGO_TARGET_DIR:-target}/release/examples/core_math_check64" "$f" "$records/$f.bin"
done
